// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address recipient, uint256 amount) public {
        // 1. restrict to admissible inputs: any address and any amount are fine
        // 2. set up the scenario: initialize the contract with dummy addresses
        c.init(address(0x1), address(0x2), address(0x3));
        uint256 prevCount = c.proposalCount();
        vm.prank(address(0xB0B));
        c.newGrantProposal(recipient, amount);
        uint256 newCount = c.proposalCount();
        // 3. The reference satisfies newCount == prevCount + 1; the bug has newCount == prevCount
        assertTrue(newCount == prevCount + 1);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address recipient, uint256 amount) public {
        vm.assume(recipient != address(0));
        // Initialize the contract with dummy addresses so newGrantProposal can be called
        c.init(address(1), address(2), address(3));
        uint256 beforeProposalCount = c.proposalCount();
        vm.prank(address(1234));
        c.newGrantProposal(recipient, amount);
        assertTrue(c.proposalCount() > beforeProposalCount);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint8 calls) public {
        vm.assume(calls > 0);
        c.init(address(0x100), address(0x200), address(0x300));
        for (uint8 i = 0; i < calls; i++) {
            c.newGrantProposal(address(0x400), 100);
        }
        assertTrue(c.proposalCount() == calls);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address _vader, address _usdv, address _vault) public {
        require(true);
        c.init(_vader, _usdv, _vault);
        assert(c.VADER() == _vader);
    }
}
